#!/usr/bin/env node
/**
 * Builds the vocabulary artefacts from data/vocabulary.source.json:
 *   - src/data/words.json   bundled with the app (offline use, local mode)
 *   - supabase/seed.sql     idempotent upsert of the same rows into public.words
 *
 * Word IDs are deterministic UUIDv5 values derived from the word, so the app's
 * bundled data and the database always agree on IDs and re-running the seed
 * never duplicates rows or orphans user progress.
 *
 * Usage: node scripts/build-vocab.mjs [--check]
 *   --check  exit non-zero if the generated files are out of date (for CI).
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const NAMESPACE = '6f1b7d0e-3c2a-4e57-9a8b-2d4c5e6f7a81'; // LexiCore vocabulary namespace
const POS = new Set(['n.', 'v.', 'adj.', 'adv.', 'prep.', 'conj.', 'phr.']);
const EXTRA_VARIANTS = { meager: ['meagre'], favorable: ['favourable'] };

export function uuidv5(name, namespace = NAMESPACE) {
  const ns = Buffer.from(namespace.replace(/-/g, ''), 'hex');
  const hash = createHash('sha1').update(Buffer.concat([ns, Buffer.from(name, 'utf8')])).digest();
  const b = hash.subarray(0, 16);
  b[6] = (b[6] & 0x0f) | 0x50;
  b[8] = (b[8] & 0x3f) | 0x80;
  const h = b.toString('hex');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

function variantsFor(word) {
  const v = new Set(EXTRA_VARIANTS[word] ?? []);
  if (/ize$/.test(word)) v.add(word.replace(/ize$/, 'ise'));
  return [...v];
}

function validate(src) {
  const errors = [];
  const seen = new Set();
  src.forEach((e, i) => {
    const at = `entry ${i + 1} (${e.word ?? '?'})`;
    if (!/^[a-z][a-z' -]*$/.test(e.word ?? '')) errors.push(`${at}: invalid word`);
    if (seen.has(e.word)) errors.push(`${at}: duplicate word`);
    seen.add(e.word);
    if (!POS.has(e.partOfSpeech)) errors.push(`${at}: invalid partOfSpeech ${e.partOfSpeech}`);
    if (!e.ja || !e.en) errors.push(`${at}: missing ja/en definition`);
    if (!Array.isArray(e.synonyms) || e.synonyms.length === 0) errors.push(`${at}: needs synonyms`);
    if (e.synonyms?.includes(e.word)) errors.push(`${at}: lists itself as a synonym`);
    if (!Number.isInteger(e.rank)) errors.push(`${at}: rank must be an integer`);
  });
  return errors;
}

export function buildWords(src) {
  return src.map((e) => ({
    id: uuidv5(e.word),
    word: e.word,
    ipa: e.ipa ?? null,
    audioUrl: e.audioUrl ?? null,
    partOfSpeech: e.partOfSpeech,
    senses: [{ partOfSpeech: e.partOfSpeech, ja: e.ja, en: e.en }, ...(e.extraSenses ?? [])],
    examples: e.examples ?? [],
    synonyms: e.synonyms,
    antonyms: e.antonyms ?? [],
    collocations: e.collocations ?? [],
    derivatives: e.derivatives ?? [],
    etymology: e.etymology ?? null,
    difficulty: e.difficulty ?? 4,
    examTags: e.examTags ?? ['advanced'],
    synonymGroup: e.synonymGroup ?? null,
    spellingVariants: variantsFor(e.word),
    rank: e.rank,
  }));
}

const sqlText = (s) => (s === null || s === undefined ? 'null' : `'${String(s).replace(/'/g, "''")}'`);
const sqlJson = (v) => `${sqlText(JSON.stringify(v))}::jsonb`;
const sqlArr = (a) => (a.length ? `array[${a.map(sqlText).join(',')}]::text[]` : `'{}'::text[]`);

export function buildSeed(words) {
  const rows = words.map(
    (w) =>
      `(${sqlText(w.id)}, ${sqlText(w.word)}, ${sqlText(w.ipa)}, ${sqlText(w.audioUrl)}, ${sqlText(w.partOfSpeech)}, ` +
      `${sqlJson(w.senses)}, ${sqlJson(w.examples)}, ${sqlArr(w.synonyms)}, ${sqlArr(w.antonyms)}, ` +
      `${sqlArr(w.collocations)}, ${sqlJson(w.derivatives)}, ${sqlText(w.etymology)}, ${w.difficulty}, ` +
      `${sqlJson({ tags: w.examTags })}, ${sqlText(w.synonymGroup)}, ${sqlArr(w.spellingVariants)}, ${w.rank})`,
  );
  return `-- GENERATED by scripts/build-vocab.mjs from data/vocabulary.source.json. Do not edit by hand.
-- Idempotent: safe to run repeatedly. Never deletes words (user progress references them).
insert into public.words
  (id, word, ipa, audio_url, part_of_speech, definitions, examples, synonyms, antonyms,
   collocations, derivatives, etymology, difficulty, exam_relevance, synonym_group, spelling_variants, rank)
values
${rows.join(',\n')}
on conflict (id) do update set
  word = excluded.word, ipa = excluded.ipa, audio_url = excluded.audio_url,
  part_of_speech = excluded.part_of_speech, definitions = excluded.definitions,
  examples = excluded.examples, synonyms = excluded.synonyms, antonyms = excluded.antonyms,
  collocations = excluded.collocations, derivatives = excluded.derivatives,
  etymology = excluded.etymology, difficulty = excluded.difficulty,
  exam_relevance = excluded.exam_relevance, synonym_group = excluded.synonym_group,
  spelling_variants = excluded.spelling_variants, rank = excluded.rank;
`;
}

function main() {
  const check = process.argv.includes('--check');
  const src = JSON.parse(readFileSync(join(root, 'data/vocabulary.source.json'), 'utf8'));
  const errors = validate(src);
  if (errors.length) {
    console.error(errors.join('\n'));
    process.exit(1);
  }
  const words = buildWords(src);
  const outputs = {
    'src/data/words.json': JSON.stringify(words) + '\n',
    'supabase/seed.sql': buildSeed(words),
  };
  let stale = false;
  for (const [rel, content] of Object.entries(outputs)) {
    const path = join(root, rel);
    const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
    if (current === content) continue;
    if (check) {
      console.error(`${rel} is out of date. Run: node scripts/build-vocab.mjs`);
      stale = true;
    } else {
      writeFileSync(path, content);
      console.log(`wrote ${rel}`);
    }
  }
  if (stale) process.exit(1);
  console.log(`${words.length} words OK`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
